window.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",t=>{t.preventDefault();const n=document.querySelector(e.getAttribute("href"));if(!n)return;const o=window.pageYOffset,r=n.offsetTop-o;let i=null;requestAnimationFrame(function e(t){i||(i=t);const n=t-i,a=Math.min(n/2e3,1),c=a<.5?4*a*a*a:1-Math.pow(-2*a+2,3)/2;window.scrollTo(0,o+r*c),n<2e3&&requestAnimationFrame(e)})})})});